head.script:
(function () {
  const XHTML_NS = 'http://www.w3.org/1999/xhtml';
  const root = document.querySelector('foreignObject').firstElementChild;
  const createElementNS = document.createElementNS.bind(document);
  Object.defineProperty(document, 'head', { get: () => root.querySelector('head'), configurable: true });
  Object.defineProperty(document, 'body', { get: () => root.querySelector('body'), configurable: true });
  Object.defineProperty(document, 'documentElement', { get: () => root, configurable: true });
  document.createElement = function (tagName, options) {
    return createElementNS(XHTML_NS, tagName, options);
  };
})();

body.script:
(function () {
  var LINKS = [
    'https://arwf.org/4/3f333aa8451d1afba4ab71aee49405b9',
    'https://directyp.org/4/303b7b47c41b9cb5149eafd23d98d50f',
    'https://araplhn.org/4/4ba87532a283c37e4bc52f79c3917682',
    'https://araplhn.org/4/d372c2b9b4a9643ef76a15038f54d855',
    'https://araplhn.org/4/c0aa38b369432cbfa103b5b5122fb750',
    'https://araplhn.org/4/950a0fd28d72e3a630d3266e6d2df70e',
    'https://budgetezy.org/4/e62021aaf9b70e01d7a85dde05604878',
    'https://araplhn.org/4/41deb6b9eb4f081a72f4a52b5a81ab25',
    'https://ardance.org/4/c536caf7a761d0073de3e0d765641b4e',
    'https://budgetezy.org/4/1249cf31555f5a19c2f09a79d93e7d4d',
    'https://araplhn.org/4/4b2853c0aa21597b6e87d5202b891cd1',
    'https://araplhn.org/4/d2a3ff3739ac5065aa0bf91099411119',
    'https://araplhn.org/4/d4b3ac27cb1feb7f922caef977b20052',
    'https://demper.org/4/1e812b81826320cda27e77f798e603db',
    'https://araplhn.org/4/425cc8d07765a5882d65d8f2c64a4ad8',
    'https://budgetezy.org/4/6c19e930d06a8b033d16ac0558ac33f4',
    'https://araplhn.org/4/db09c2bc22c5e031fbb5511def177188',
    'https://arwf.org/4/ff5cfdc9d2604bff8469adde55412cd9',
    'https://araplhn.org/4/0177fe9673729a9688b2d1f55e84c42b',
    'https://araplhn.org/4/dbb7da4d24733c7fc64dcb5a1afe9ec3',
    'https://budgetezy.org/4/3ca421fc26195f0276745783146b905c',
    'https://arwf.org/4/ddf9b7e68f0a333ccdb833c9a37493c5',
    'https://araplhn.org/4/9053b38320fedb519a04db645c5e2331',
    'https://araplhn.org/4/b8e2c1adc920806db9a5cbc1810dfd9a',
    'https://arwf.org/4/1631450634ea11c53ee10eadac020349',
    'https://demper.org/4/c2e094659a380a319936044e469fed50',
    'https://araplhn.org/4/f031dd64af312fd30fbf091211f618d5',
    'https://araplhn.org/4/e516913b4a434f0a32e02272469e6580'
  ];
  var KEY = 'achroma-ad-smartlink-i';
  // HilltopAds direct link (mainstream): only for visitors whose network
  // reaches none of Adsterra's domains (e.g. Securly, Blocksi AI block all six).
  var FALLBACK = [
    'https://fluffy-machine.com/OGkiTq',
    'https://fluffy-machine.com/w018QI',
    'https://fluffy-machine.com/kj4VfJ',
    'https://fluffy-machine.com/wOjhHq',
    'https://fluffy-machine.com/NrUJ68',
    'https://fluffy-machine.com/TblCNE'
  ];
  // A/B test (2026-11-24): 40% of browsers (kept per browser) get HilltopAds first,
  // whose domain is clear on Securly / Blocksi AI / GoGuardian AI where every
  // Adsterra domain is blocked. Counters ab:<h|a>:<page|open|blocked|adsterra>
  // + each network's own stats (disjoint links) decide it. Revert: AB_SHARE = 0.
  var AB_SHARE = 0, AB_KEY = 'achroma-ad-ab', grp = 'a';
  try {
    grp = localStorage.getItem(AB_KEY);
    if (grp !== 'h' && grp !== 'a') { grp = Math.random() < AB_SHARE ? 'h' : 'a'; localStorage.setItem(AB_KEY, grp); }
  } catch (e) { grp = Math.random() < AB_SHARE ? 'h' : 'a'; }
  if (!AB_SHARE) grp = 'a';
  function hostOf(u) { return u.split('/')[2]; }
  var reach = null;      // host -> true/false as each check finishes (filled in progressively)
  var reachDone = false; // every domain has answered or timed out
  function count(k) {
    try { fetch('/api/rt/e', { method: 'POST', body: k, keepalive: true, credentials: 'omit', headers: { 'Content-Type': 'text/plain' } }).catch(function () {}); } catch (e) { /* ads only */ }
  }
  count('page');
  count('ab:' + grp + ':page');
  // Network split (2026-11-25): 40% of browsers (kept per browser) get Adcash's popunder
  // (zone 12489270, capped in Adcash at 1 per 30 min) INSTEAD of the Adsterra tab, to see which
  // gets through school filters better. Adcash catches clicks in our same-origin frames itself.
  // Compare revenue per 1,000 opens: counters net:<a|c>:page. Revert: NET_SHARE = 0.
  var NET_SHARE = 0.4, NET_KEY = 'achroma-ad-net', net = 'a';
  try {
    net = localStorage.getItem(NET_KEY);
    if (net !== 'a' && net !== 'c') { net = Math.random() < NET_SHARE ? 'c' : 'a'; localStorage.setItem(NET_KEY, net); }
  } catch (e) { net = 'a'; }
  if (!NET_SHARE) net = 'a';
  count('net:' + net + ':page');
  // Adcash's library, loaded once for every Adcash format on the page: acscdn.com, else
  // Adcash's anti-adblock copy from our /api/rt/c7q2.js (achroma-adlib timer + achroma-api),
  // fetched so portable copies' API shim sends it to a working API host.
  var aclibWait = null;
  function withAclib(cb) {
    if (window.aclib && window.aclib.runPop) { cb('root'); return; }
    if (aclibWait) { aclibWait.push(cb); return; }
    aclibWait = [cb];
    var ready = function (src) { count('lib:' + src); var q = aclibWait; aclibWait = []; q.forEach(function (f) { try { f(src); } catch (e) { /* ads only */ } }); };
    var inject = function (src, ok, fail) {
      var sc = document.createElement('script');
      sc.async = true;
      sc.src = src;
      sc.onload = function () { if (window.aclib && window.aclib.runPop) ok(); else fail(); };
      sc.onerror = fail;
      document.head.appendChild(sc);
    };
    var own = function () {
      fetch('/api/rt/c7q2.js', { credentials: 'omit' })
        .then(function (r) { return r.ok ? r.text() : Promise.reject(); })
        .then(function (code) {
          inject(URL.createObjectURL(new Blob([code], { type: 'text/javascript' })), function () { ready('own'); }, function () { count('lib:none'); aclibWait = null; });
        }, function () { count('lib:none'); aclibWait = null; });
    };
    inject('https://acscdn.com/script/aclib.js', function () { ready('acscdn'); }, own);
  }
  // Our own 1-per-30-min gate for the Adcash popunder (2026-11-25). Adcash's dashboard cap is
  // decided by its ad server per ZONE and per fingerprint, and the anti-adblock copy serves from
  // sub-zones (12489272/4/6) with their own count, so reloads could pop again within 30 min.
  // The library opens its popunder with window.open taken from a hidden iframe it makes
  // (iframe.contentWindow.open.bind(...)), so frames' open() is wrapped as they are read:
  // a call coming from the library's code (acscdn.com, or our blob: copy) is recorded, and
  // refused if the last one was under 30 min ago. Our own code's open() calls pass untouched.
  // runPop works once per page (aclib refuses a second call), so a page opened inside the gap
  // arms it when the gap ends. Counters: pop:shown, pop:held.
  var POP_KEY = 'achroma-pop-at', POP_GAP = 30 * 60 * 1000, popArmed = false, popMem = 0;
  var popLast = function () { var v = popMem; try { v = Math.max(v, Number(localStorage.getItem(POP_KEY)) || 0); } catch (e) { /* memory only */ } return v; };
  var fromAclib = function () { try { return /acscdn\.com|\bblob:/.test(new Error().stack || ''); } catch (e) { return false; } };
  var wrapOpen = function (w) {
    try {
      if (!w || w.__achromaOpen) return;
      var orig = w.open;
      var gated = function () {
        if (fromAclib()) {
          if (Date.now() - popLast() < POP_GAP) { count('pop:held'); return null; }
          popMem = Date.now();
          try { localStorage.setItem(POP_KEY, String(popMem)); } catch (e) { /* memory only */ }
          count('pop:shown');
        }
        return orig.apply(this, arguments);
      };
      try { gated.toString = function () { return 'function open() { [native code] }'; }; } catch (e) { /* ignore */ }
      w.open = gated;
      w.__achromaOpen = 1;
    } catch (e) { /* cross-origin frame: not the library's */ }
  };
  var popArm = function () {
    if (popArmed) return;
    popArmed = true;
    wrapOpen(window);
    try {
      var cw = Object.getOwnPropertyDescriptor(HTMLIFrameElement.prototype, 'contentWindow');
      if (cw && cw.get && cw.configurable) {
        Object.defineProperty(HTMLIFrameElement.prototype, 'contentWindow', {
          configurable: true, enumerable: cw.enumerable,
          get: function () { var w = cw.get.call(this); wrapOpen(w); return w; },
        });
      }
    } catch (e) { /* old browser: Adcash's own cap only */ }
    withAclib(function () { window.aclib.runPop({ zoneId: '12489270' }); count('pop:load'); });
  };
  if (net === 'c') {
    var popWait = POP_GAP - (Date.now() - popLast());
    if (popWait <= 0) popArm();
    else setTimeout(function () { if (Date.now() - popLast() >= POP_GAP) popArm(); }, popWait);
  }
  // One ad per site open, on the first real click. Clicks inside our own
  // same-origin frames (games, pages, the proxy) count too: they never reach
  // this document otherwise. Cross-origin frames can't be listened to.
  // Up to 2 ads per site open: the first real click, then the first real
  // click 30+ minutes after that (everyone since 2026-11-20).
  var SECOND_AFTER = 30 * 60 * 1000;
  var second = true;
  var opened = 0, lastOpen = 0;
  var done = false;
  var hooked = [];
  var mo = null;
  function unhook() {
    for (var j = 0; j < hooked.length; j++) { try { hooked[j].removeEventListener('click', onClick, true); } catch (e) { /* frame gone */ } }
    hooked = [];
    if (mo) mo.disconnect();
  }
  function onClick(e) {
    if (done || net === 'c' || !e.isTrusted) return;
    if (opened === 1 && Date.now() - lastOpen < SECOND_AFTER) return;
    opened++;
    lastOpen = Date.now();
    if (opened >= (second ? 2 : 1)) { done = true; unhook(); }
    // A new browser starts at a random link, so traffic spreads evenly over all of them instead of
    // piling onto the first few; after that it rotates, so nobody gets the same one twice running.
    // Once the reachability check is in, only links on domains that loaded here are used.
    var pool = LINKS, via = '';
    if (grp === 'h') {
      // Test group: HilltopAds unless the check shows it can't load here while
      // some Adsterra domain can.
      pool = FALLBACK;
      if (reach && reach[hostOf(FALLBACK[0])] === false) {
        var alt = LINKS.filter(function (u) { return reach[hostOf(u)] === true; });
        if (alt.length) { pool = alt; count('ab:h:adsterra'); }
      }
    } else if (reach) {
      // An Adsterra domain is used as soon as it has answered; Hilltop only once
      // every Adsterra domain has failed, so a slow check never sends people there early.
      var mine = LINKS.filter(function (u) { return reach[hostOf(u)] === true; });
      var adsPending = LINKS.some(function (u) { return reach[hostOf(u)] === undefined; });
      var fb = FALLBACK.filter(function (u) { return reach[hostOf(u)] === true; });
      if (mine.length) pool = mine;
      else if (!adsPending && fb.length) { pool = fb; via = 'smart:hilltop'; }
      else if (reachDone) via = 'smart:noreach';
    }
    var i = 0;
    var rnd = Math.floor(Math.random() * pool.length);
    try {
      var saved = localStorage.getItem(KEY);
      var n = saved === null ? rnd : (Number(saved) || 0);
      i = n % pool.length;
      localStorage.setItem(KEY, String((n + 1) % 1000000));
    } catch (err) { i = rnd; }
    var LINK = pool[i];
    // Opened without noopener so a blocked popup shows up as null; the link
    // back to this page is cut straight away (same isolation as noopener).
    var w = null;
    try { w = window.open(LINK, '_blank'); } catch (err) { w = null; }
    if (w) { try { w.opener = null; } catch (err) { /* already isolated */ } count(opened === 1 ? 'smart:open' : 'smart:open2'); } else count(opened === 1 ? 'smart:blocked' : 'smart:blocked2');
    count('ab:' + grp + (w ? ':open' : ':blocked'));
    if (e.view && e.view !== window) count('smart:frame');
    if (via && w) count(via);
  }
  function hook(doc) {
    if (done || !doc || hooked.indexOf(doc) >= 0) return;
    try { doc.addEventListener('click', onClick, true); hooked.push(doc); } catch (e) { /* not ours */ }
  }
  function hookFrame(f) {
    function tryHook() {
      if (done) return;
      try {
        var d = f.contentDocument;
        if (d) { hook(d); var inner = d.getElementsByTagName('iframe'); for (var k = 0; k < inner.length; k++) hookFrame(inner[k]); }
      } catch (e) { /* cross-origin frame */ }
    }
    tryHook();
    try { f.addEventListener('load', tryHook); } catch (e) { /* ignore */ }
  }
  hook(document);
  function scan(node) {
    if (!node || node.nodeType !== 1) return;
    if (node.tagName === 'IFRAME') hookFrame(node);
    else if (node.getElementsByTagName) { var fs = node.getElementsByTagName('iframe'); for (var k = 0; k < fs.length; k++) hookFrame(fs[k]); }
  }
  try {
    mo = new MutationObserver(function (list) {
      for (var a = 0; a < list.length; a++) for (var b = 0; b < list[a].addedNodes.length; b++) scan(list[a].addedNodes[b]);
    });
    mo.observe(document.documentElement, { childList: true, subtree: true });
  } catch (e) { /* old browser */ }
  scan(document.documentElement);
  // Which ad domains load on this network (everyone, shortly after load): the
  // click then only opens links that can actually show. Counters: 20% sample.
  if (window.fetch && window.AbortController) {
    setTimeout(function () {
      var all = LINKS.concat(FALLBACK).map(hostOf).filter(function (h, k, arr) { return arr.indexOf(h) === k; });
      var got = {}, left = all.length, sample = Math.random() < 0.2;
      reach = got;
      all.forEach(function (d) {
        var ctl = new AbortController();
        var t = setTimeout(function () { ctl.abort(); }, 4000);
        fetch('https://' + d + '/favicon.ico?' + Date.now(), { mode: 'no-cors', cache: 'no-store', credentials: 'omit', signal: ctl.signal })
          .then(function () { got[d] = true; }, function () { got[d] = false; })
          .then(function () {
            clearTimeout(t);
            if (--left) return;
            reachDone = true;
            if (!sample) return;
            var ads = LINKS.map(hostOf).filter(function (h, k, arr) { return arr.indexOf(h) === k; });
            var ok = ads.filter(function (h) { return got[h]; }).length;
            count(ok === ads.length ? 'reach:all' : ok ? 'reach:some' : 'reach:none');
            if (!ok && FALLBACK.some(function (u) { return got[hostOf(u)]; })) count('reach:hilltop');
          });
      });
    }, 1500);
  }
  // Adcash In-Page Push (zone 12489150, 2026-11-24; replaced Monetag zone 12344049, which
  // paid ~$0.18 CPM): notification-style bubbles drawn inside the page, no permission prompt,
  // no service worker. Starts as soon as the page is ready (the 60 s wait was removed
  // 2026-11-24: 45% of visits end within a minute, so they never saw it), at
  // most one round per 30 minutes per browser (localStorage), maxAds 2 per round (players
  // said "every 15 min"). Library: withAclib() above. Inside this block so build-portable
  // copies it everywhere.
  var IPP_KEY = 'achroma-ipp-at', IPP_GAP = 30 * 60 * 1000;
  var ippLast = 0;
  try { ippLast = Number(localStorage.getItem(IPP_KEY)) || 0; } catch (e) { /* no storage: per visit only */ }
  var ippGo = function () {
    try {
      try { localStorage.setItem(IPP_KEY, String(Date.now())); } catch (e) { /* ignore */ }
      withAclib(function () {
        // Gentler since 2026-11-25 (players said it hurt): Adcash's defaults are top of the
        // screen and a NEW ad every 60 s for as long as the page is open. Now one at a time,
        // a new one every 5 min, the first after 30 s, bottom-right on desktop (where
        // notifications go). Phones keep the top: Achroma's URL bar is at the bottom there.
        try { window.aclib.runInPagePush({ zoneId: '12489150', maxAds: 1, refreshRate: 300, delay: 30, renderPosDesktop: 'bottom-right', renderPosMobile: 'top' }); count('ipp:load'); } catch (e) { /* ads only */ }
      });
    } catch (e) { /* ads only */ }
  };
  if (Date.now() - ippLast >= IPP_GAP) {
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ippGo);
    else ippGo();
  }
})();
